// Bài 9.3 — kind cho biết hình dạng; trong mỗi case chỉ đọc trường của hình dạng đó
function render(state) {
  switch (state.kind) {
    case 'loading':
      return 'Loading...';
    case 'error':
      return 'Error: ' + state.message;
    case 'done': {
      const n = state.items.length;
      let text = n + (n === 1 ? ' item' : ' items');
      if (n > 0) text += ': ' + state.items.slice(0, 3).join(', ') + (n > 3 ? ' and ' + (n - 3) + ' more' : '');
      return text;
    }
    case 'empty':
      return 'Nothing here yet';
    default:
      throw new Error('unhandled kind: ' + state.kind);   // trong TS: const x: never = state;
  }
}

